from service import conectar, arquive_service
from service.enviar import enviarTexto


def main():
    API_KEY = "40028922"
    escolha = input("1 - Criar Conexao\n2 - Conectar Conexao\n3 - Deletar Conexao\n4 - Mandar Mensagem\nOq c ke faze?\n")

    meu_qr_data_url = "data:image/jpeg;base64,"

    arquive_service.print_qrCode(meu_qr_data_url)

    if escolha == '1':
        nome = input("Qual o nome da conexao?")
        numero = input("Qual o numero da conexao?")
        conectar.criarConexao(nome, API_KEY, numero)

    elif escolha == '2':
        nome = input("Qual o nome da conexao?")
        conectar.conectarConexao(nome, API_KEY)

    elif escolha == '3':
        nome = input("Qual o nome da conexao?")
        conectar.deletarConexao(nome, API_KEY)

    elif escolha == '4':
        nome = input("Qual o nome da conexao?")
        numero = input("Qual o numero da conexao?")
        texto = input("Qual o conteudo da mensagem?")

        enviarTexto(nome, numero, texto, API_KEY)

if __name__ == '__main__':
    main()